import React, { useState, useEffect } from 'react';
import axios from 'axios';
import '../../styles/table.scss';

const WorkAnniversaryAlert = () => {
  const [alerts, setAlerts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Tạm gọi trực tiếp hoặc đưa vào service sau
    const fetchAlerts = async () => {
      try {
        // Trong thực tế, bạn sẽ cần tạo một route để gọi check_anniversary()
        // Vì hiện tại anniversary_alert.py là một script riêng lẻ.
        // Giả lập dữ liệu nếu chưa có API
        setTimeout(() => {
          setAlerts([
            { employee: "Nguyễn Văn An", year: 20, type: "exact", message: "Chúc mừng Nguyễn Văn An kỷ niệm 20 năm làm việc! 🎉" },
            { employee: "Lê Thị Bình", year: 18, type: "this_week", message: "Sắp tới: Lê Thị Bình sẽ kỷ niệm 18 năm vào 3 ngày nữa." }
          ]);
          setLoading(false);
        }, 1000);
      } catch (error) {
        setLoading(false);
      }
    };
    fetchAlerts();
  }, []);

  return (
    <div className="alert-page animate-fade-in" style={{ padding: '2rem' }}>
      <div style={{ marginBottom: '2rem' }}>
        <h1 style={{ fontSize: '1.875rem', fontWeight: 'bold', color: '#1f2937' }}>Cảnh Báo Kỷ Niệm (Work Anniversary)</h1>
        <p style={{ color: '#6b7280' }}>Nhân viên có ngày kỷ niệm làm việc trong tháng này</p>
      </div>

      <div className="modern-table-container">
        {loading ? (
          <div style={{ padding: '2rem', textAlign: 'center' }}>Đang tải dữ liệu cảnh báo...</div>
        ) : (
          <table>
            <thead>
              <tr>
                <th>Nhân viên</th>
                <th>Số năm</th>
                <th>Trạng thái</th>
                <th>Thông điệp</th>
              </tr>
            </thead>
            <tbody>
              {alerts.map((alert, index) => (
                <tr key={index}>
                  <td style={{ fontWeight: '500' }}>{alert.employee}</td>
                  <td><span className="status-badge present">{alert.year} năm</span></td>
                  <td>
                    {alert.type === 'exact' 
                      ? <span className="status-badge success" style={{backgroundColor: '#10b981', color: 'white'}}>Hôm nay</span>
                      : <span className="status-badge warning" style={{backgroundColor: '#f59e0b', color: 'white'}}>Sắp tới</span>}
                  </td>
                  <td>{alert.message}</td>
                </tr>
              ))}
              {alerts.length === 0 && (
                <tr>
                  <td colSpan="4" style={{ textAlign: 'center', padding: '2rem' }}>Không có sự kiện kỷ niệm nào</td>
                </tr>
              )}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
};

export default WorkAnniversaryAlert;
